package com.dailyaccounts.manager;

import android.app.*;import android.os.Bundle;import android.content.*;import android.database.Cursor;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity {
    DB db; LinearLayout root,body; final int GREEN=0xff176b5b, DARK=0xff123f38, RED=0xffb3261e; ArrayList<Long> ids=new ArrayList<>(); ArrayList<String> names=new ArrayList<>();
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new DB(this); showHome();}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff202124);t.setPadding(4,8,4,8);return t;}
    Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());return b;}
    EditText edit(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setPadding(12,8,12,8);return e;}
    void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff5f7f7);TextView h=text(title,22);h.setTextColor(-1);h.setTypeface(null,Typeface.BOLD);h.setBackgroundColor(DARK);h.setPadding(18,18,12,18);root.addView(h);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setPadding(14,10,14,24);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(-1);for(String s:new String[]{"Home","Income","Expense","Accounts","Transfer","Reports"})nav.addView(button(s,()->{switch(s){case "Home":showHome();break;case "Income":showEntry(true);break;case "Expense":showEntry(false);break;case "Accounts":showAccounts();break;case "Transfer":showTransfer();break;default:showReports();}}),new LinearLayout.LayoutParams(0,-2,1));root.addView(nav);setContentView(root);}
    void card(String title,double value,int color){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(14,10,14,10);c.setBackgroundColor(color);TextView a=text(title,14);TextView b=text("₹ "+money(value),23);b.setTypeface(null,Typeface.BOLD);c.addView(a);c.addView(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);body.addView(c,p);}
    String money(double x){return String.format(Locale.US,"%,.2f",x);} String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
    void showHome(){base("Daily Accounts Manager");double[] d=db.totals("TODAY"),m=db.totals("MONTH");card("Today's Income",d[0],0xffdff3e5);card("Today's Expense",d[1],0xffffe4e1);card("Monthly Income",m[0],0xffe2eaff);card("Monthly Expense",m[1],0xfffff0d5);double total=0;Cursor a=db.accounts();while(a.moveToNext())total+=db.balance(a.getLong(0));a.close();card("Total Available Balance",total,0xffd8eeeb);body.addView(text("Account balances",18));a=db.accounts();while(a.moveToNext())body.addView(text(a.getString(1)+"  •  ₹ "+money(db.balance(a.getLong(0))),16));a.close();body.addView(text("Recent transactions",18));Cursor c=db.recent();int n=0;while(c.moveToNext()&&n++<10)body.addView(text(c.getString(0)+"  |  "+c.getString(1)+"  |  ₹"+money(c.getDouble(2))+"\n"+c.getString(3)+"  "+c.getString(4),14));c.close();}
    void loadAccounts(){ids.clear();names.clear();Cursor c=db.accounts();while(c.moveToNext()){ids.add(c.getLong(0));names.add(c.getString(1)+" ("+c.getString(2)+")");}c.close();}
    Spinner spinner(List<String> items){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items);s.setAdapter(a);return s;}
    void showEntry(boolean income){base(income?"Add Income":"Add Expense");loadAccounts();EditText date=edit("Date (YYYY-MM-DD)");date.setText(today());body.addView(text("Date",14));body.addView(date);EditText from=edit(income?"From (person/source)":"Category (e.g. Food, Travel)");body.addView(text(income?"From":"Category",14));body.addView(from);EditText particular=edit(income?"Particular / purpose (optional)":"Particular Expense");if(!income){body.addView(text("Particular Expense",14));body.addView(particular);}EditText amount=edit("Amount ₹");amount.setInputType(8194);body.addView(text("Amount",14));body.addView(amount);EditText remark=edit("Remark");body.addView(text("Remark",14));body.addView(remark);body.addView(text(income?"Received in":"Paid from",14));Spinner acc=spinner(names);body.addView(acc);body.addView(button("Save "+(income?"Income":"Expense"),()->{try{String dt=date.getText().toString().trim();if(!dt.matches("\\d{4}-\\d{2}-\\d{2}"))throw new Exception("Date YYYY-MM-DD format mein daalein");double val=Double.parseDouble(amount.getText().toString().trim());if(val<=0)throw new Exception("Amount zero se zyada hona chahiye");if(ids.isEmpty())throw new Exception("Pehle account banayein");long account=ids.get(acc.getSelectedItemPosition());long result=db.addTx(dt,income?"INCOME":"EXPENSE",income?null:account,income?account:null,val,income?from.getText().toString().trim():null,income?null:from.getText().toString().trim(),particular.getText().toString().trim(),remark.getText().toString().trim());if(result<0)throw new Exception("Save nahi hua");Toast.makeText(this,"Saved successfully",Toast.LENGTH_SHORT).show();showHome();}catch(Exception e){Toast.makeText(this,"Check details: "+e.getMessage(),Toast.LENGTH_LONG).show();}}));}
    void showAccounts(){base("Accounts & Opening Balance");body.addView(text("Cash, UPI aur har bank ka opening balance set karein. Existing accounts ka naam/type change karne se pehle backup rakhein.",14));EditText name=edit("Account name (e.g. SBI Savings)");body.addView(name);Spinner type=spinner(Arrays.asList("BANK","CASH","UPI"));body.addView(text("Account type",14));body.addView(type);EditText opening=edit("Opening balance ₹");opening.setInputType(8194);opening.setText("0");body.addView(opening);body.addView(button("Add Account",()->{try{String nm=name.getText().toString().trim();if(nm.isEmpty())throw new Exception("Account name zaroori hai");double op=Double.parseDouble(opening.getText().toString());if(op<0)throw new Exception("Opening balance negative nahi ho sakta");if(db.addAccount(nm,type.getSelectedItem().toString(),op)<0)throw new Exception("Account save nahi hua");showAccounts();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}));body.addView(text("Your accounts",18));Cursor c=db.accounts();while(c.moveToNext())body.addView(text(c.getString(1)+" • "+c.getString(2)+"\nOpening: ₹"+money(c.getDouble(3))+" | Current: ₹"+money(db.balance(c.getLong(0))),16));c.close();}
    void showTransfer(){base("Transfer Between Accounts");loadAccounts();if(ids.size()<2){body.addView(text("Transfer ke liye kam se kam 2 accounts chahiye.",16));return;}body.addView(text("From account",14));Spinner from=spinner(names);body.addView(from);body.addView(text("To account",14));Spinner to=spinner(names);body.addView(to);EditText date=edit("Date YYYY-MM-DD");date.setText(today());body.addView(date);EditText amount=edit("Amount ₹");amount.setInputType(8194);body.addView(amount);EditText remark=edit("Remark (optional)");body.addView(remark);body.addView(button("Save Transfer",()->{try{int fi=from.getSelectedItemPosition(),ti=to.getSelectedItemPosition();if(fi==ti)throw new Exception("Source aur destination alag honi chahiye");double x=Double.parseDouble(amount.getText().toString());if(x<=0)throw new Exception("Amount zero se zyada hona chahiye");String dt=date.getText().toString();if(!dt.matches("\\d{4}-\\d{2}-\\d{2}"))throw new Exception("Date format YYYY-MM-DD rakhein");if(db.addTx(dt,"TRANSFER",ids.get(fi),ids.get(ti),x,null,null,null,remark.getText().toString())<0)throw new Exception("Save failed");showHome();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}));}
    void showReports(){base("Reports & AI Insights");double[] d=db.totals("TODAY"),m=db.totals("MONTH");body.addView(text("DAILY SUMMARY",18));body.addView(text("Income: ₹"+money(d[0])+"\nExpense: ₹"+money(d[1])+"\nNet: ₹"+money(d[0]-d[1]),16));body.addView(text("MONTHLY SUMMARY",18));body.addView(text("Income: ₹"+money(m[0])+"\nExpense: ₹"+money(m[1])+"\nNet: ₹"+money(m[0]-m[1]),16));body.addView(text("Basic insight",18));if(m[1]>m[0])body.addView(text("Alert: Is month expense income se zyada hai. Categories review karein.",15));else body.addView(text("Is month recorded income expense se zyada ya barabar hai. Budget aur category trends review karein.",15));body.addView(text("Transaction history",18));Cursor c=db.report();while(c.moveToNext())body.addView(text(c.getString(0)+" | "+c.getString(1)+" | ₹"+money(c.getDouble(2))+"\n"+c.getString(3)+" "+c.getString(4)+"\n"+c.getString(5),14));c.close();body.addView(text("Note: Yeh rule-based insight hai; advanced AI analysis aur PDF/CSV backup next implementation phase mein add karna hoga.",13));}
}
